private static CronDefinition quartz() {
    return CronDefinitionBuilder.defineCron()
            .withSeconds().withStrictRange().and()
            .withMinutes().withStrictRange().and()
            .withHours().withStrictRange().and()
            .withDayOfMonth().withValidRange(1, 31).supportsL().supportsW().supportsLW().supportsQuestionMark().and() // remove withStrictRange()
            .withMonth().withValidRange(1, 12).and() // remove withStrictRange()
            .withDayOfWeek().withValidRange(0, 7).withMondayDoWValue(1).supportsHash().supportsL().supportsQuestionMark().and() // remove withStrictRange()
            .withYear().withValidRange(1970, 2099).optional().and() // remove withStrictRange()
            .withCronValidation(CronConstraintsFactory.ensureEitherDayOfWeekOrDayOfMonth())
            .instance();
}

private static CronDefinition quartz() {
    return CronDefinitionBuilder.defineCron()
            .withSeconds().withStrictRange().and()
            .withMinutes().withStrictRange().and()
            .withHours().withStrictRange().and()
            .withDayOfMonth().withValidRange(1, 31).supportsL().supportsW().supportsLW().supportsQuestionMark().and()  // Reverting 32 to 31
            .withMonth().withValidRange(1, 12).and()  // Correcting range to 1-12
            .withDayOfWeek().withValidRange(1, 7).withMondayDoWValue(2).supportsHash().supportsL().supportsQuestionMark().and()  // The value for DoW remains with Monday = 2
            .withYear().withValidRange(1970, 2099).optional().and()
            .withCronValidation(CronConstraintsFactory.ensureEitherDayOfWeekOrDayOfMonth())
            .instance();
}

